// ❌ OLD: Returning target[key] bypasses the receiver argument. When the
// target has a getter, that getter runs with `this === target`, NOT the
// proxy — so the getter cannot observe proxy-internal state and other
// traps are skipped for the property access chain.
const target = {
  _count: 0,
  get count() {
    // `this` here should be the proxy in correct code, but with the
    // bad trap below it is the raw target.
    return this._count;
  }
};

const proxy = new Proxy(target, {
  get(obj, key) {
    // ❌ OLD: no receiver passed — getter `this` becomes `target`
    return obj[key];
  }
});

console.log(proxy.count); // 0, but `this` inside the getter was `target`

// ✅ NEW: Reflect.get(target, key, receiver) performs the standard
// [[Get]] and forwards `receiver` as the getter's `this`. Getters now
// observe the proxy, so proxy-level state and later traps compose
// correctly.
const target = {
  _count: 0,
  get count() {
    // `this` is the proxy, so a get trap on `_count` will fire.
    return this._count;
  }
};

const proxy = new Proxy(target, {
  get(obj, key, receiver) {
    // ✅ NEW: forward receiver — getter `this` === proxy
    return Reflect.get(obj, key, receiver);
  }
});

console.log(proxy.count); // 0, and `this._count` hit the proxy get trap
